head.script:
scwin.test_expression = function(value) {
    return value + "_test";
};
scwin.gridView1_ongroupby = function(options) {
    var flag = true;
    if (flag) {
        options.closeGroup = true;
        options.groupbyHeader = [{
            colSpan: "10",
            inputType: "expression",
            expression: " toggle() + depthStr() + ' [ '+ SUM('col3') +',' + count() + ' 건 ] ' ",
            align: "left"
        }];
        options.groupbyFooter = [{
                colSpan: "7"
            },
            {
                colSpan: "3",
                inputType: "expression",
                expression: " SUM('col3')",
                displayFormatter: "countFormatFunction",
                align: "center"
            }
        ];
        gridView1.groupby(options); //실제 groupby 실행
    } else {
        return false;
    }
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal = function() {
    scwin.simulateWrapper('#gridView1_column23', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_0').text().indexOf('label_a1') != -1;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_2_0').text().indexOf('label_a2') != -1;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_4_0').text().indexOf('label_a3') != -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 그리드뷰의 select컬럼을 groupby한다.(마우스로 드래그해서 위로 이동)
    //1. After running the sample file, group the select column of the grid view (drag it with the mouse to move up).
    //Verify step 1. The select column is groupby and displayed as label values (abel_a1, abel_a2, abel_a3).
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
